{
  "interpretation": {
    "name": "Line2NutrunnerFixedTorque",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2 of line 2, tighten the fasteners using the operator-specified fixed target torque instead of the MES program, evaluate and record the result, then return and release the tool.",
    "constraints": [
      "Operator requests a fixed target torque of 210 N*m instead of the MES tightening program (get-program omitted at operator request). This value is deliberately not placed in the Recipe, because E4 says torque must come from services.",
      "The tool must be reserved before use and released afterwards.",
      "transport-tool must be delegated to agvexecutor.",
      "The tool must be at st2 before configure-tool and tighten-fasteners.",
      "The tightening must be evaluated and recorded (E5)."
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": ["operator-specified fixed target torque override of the MES program"],
    "omit_services": ["get-program"]
  },
  "recipe": {
    "name": "line2-nr7-fixed-torque-tightening",
    "first_action": "reserve",
    "actions": [
      {
        "name": "reserve",
        "next": "move-to-station",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "move-to-station",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "verify",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-nr7"], "dep": ["reserve-nr7"], "executor": null, "params": {}},
          {"name": "tighten-nr7", "service": "tighten-fasteners", "next": [], "dep": ["configure-nr7", "reserve-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "verify",
        "next": "return-tool",
        "steps": [
          {"name": "evaluate-nr7", "service": "evaluate-tightening", "next": [], "dep": ["tighten-nr7"], "executor": null, "params": {}},
          {"name": "record-nr7", "service": "record-tightening", "next": [], "dep": ["tighten-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "return-tool",
        "next": "release",
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "release",
        "next": null,
        "steps": [
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
